import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DiAOIirN.js";var i=JSON.parse(`{"title":"Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md","lastUpdated":1788356799000}`),a={name:`reference/tools.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to “Tools”">​</a></h1><p>Seven tools. Four are always registered and none of them can put a message on the wire; three send, and those are registered only when <code>SMTP_ALLOW_SEND=true</code>.</p><p>Every tool declares an <code>outputSchema</code> and answers with <code>structuredContent</code> beside the text block, so a client can use a result without parsing prose. <code>preview_mail</code> is the one that carries <code>untrusted: true</code> and <code>source: &quot;smtp&quot;</code> fields — a quoted original was written by whoever sent it, and anyone in the world can send mail. Its text block keeps the nonce fence; the structured half states the same fields rather than making a client parse it.</p><p><code>SMTP_ALLOW_TOOLS</code> and <code>SMTP_DENY_TOOLS</code> narrow the list further — see <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>. A tool that is filtered out is not built: it is absent from <code>tools/list</code> and a call answers &quot;not found&quot;.</p><h2 id="always-available" tabindex="-1">Always available <a class="header-anchor" href="#always-available" aria-label="Permalink to “Always available”">​</a></h2><h3 id="get-server-info" tabindex="-1"><code>get_server_info</code> <a class="header-anchor" href="#get-server-info" aria-label="Permalink to “get_server_info”">​</a></h3><p>No parameters. Reports the SMTP endpoint, the fixed sender, the allowlist, the limits, how many sends remain in the current hour, whether attachments are available, and — first in the payload — whether this server can send at all.</p><p>Call it before anything else. It answers &quot;can I send, and to whom&quot; without touching the network.</p><h3 id="validate-recipients" tabindex="-1"><code>validate_recipients</code> <a class="header-anchor" href="#validate-recipients" aria-label="Permalink to “validate_recipients”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>addresses</code></td><td><code>string[]</code></td><td>yes</td><td>Up to 100 addresses to check.</td></tr></tbody></table><p>Says which addresses this server may write to and which it will refuse. No connection is made and nothing is sent. Use it before composing rather than discovering a refusal afterwards.</p><h3 id="preview-mail" tabindex="-1"><code>preview_mail</code> <a class="header-anchor" href="#preview-mail" aria-label="Permalink to “preview_mail”">​</a></h3><p>Same parameters as <a href="#send-mail"><code>send_mail</code></a>, minus <code>confirm_token</code>.</p><p>Builds exactly the message <code>send_mail</code> would build — the same code path, the same headers — and returns its headers and bodies without connecting to anything. Every check a send performs runs here too: the allowlist, the recipient limit, the attachment policy and the size limit.</p><p>Attachment payloads are summarised by name, size and digest rather than printed. The rendered message comes back fenced as untrusted content, because it contains text this server did not write.</p><h3 id="test-connection" tabindex="-1"><code>test_connection</code> <a class="header-anchor" href="#test-connection" aria-label="Permalink to “test_connection”">​</a></h3><p>No parameters. Connects, negotiates TLS, authenticates and disconnects. No message is sent.</p><p>Use it to tell a configuration problem apart from a delivery problem.</p><h2 id="sending" tabindex="-1">Sending <a class="header-anchor" href="#sending" aria-label="Permalink to “Sending”">​</a></h2><p>All three ask a person to confirm before acting, using MCP elicitation, and fall back to a two-call token where the client cannot show a dialog. All three are annotated <code>destructiveHint</code>, because a message cannot be recalled. The dialog lists the recipients, the subject, the body, the quoted original and the HTML part — each caller-chosen value on its own labelled line, cut to 200 characters, with its full length in the label.</p><p>A message the SMTP server has already accepted is not sent a second time: an identical call within the approval window answers <code>already_sent</code> with the earlier <code>message_id</code>, asks nobody and spends no quota.</p><h3 id="send-mail" tabindex="-1"><code>send_mail</code> <a class="header-anchor" href="#send-mail" aria-label="Permalink to “send_mail”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>to</code></td><td><code>string[]</code></td><td>yes</td><td>Primary recipients.</td></tr><tr><td><code>cc</code></td><td><code>string[]</code></td><td>no</td><td>Visible to everyone who receives the message.</td></tr><tr><td><code>bcc</code></td><td><code>string[]</code></td><td>no</td><td>Hidden from the others. Shown separately in the confirmation.</td></tr><tr><td><code>subject</code></td><td><code>string</code></td><td>yes</td><td>One line, up to 255 characters.</td></tr><tr><td><code>body</code></td><td><code>string</code></td><td>yes</td><td>Plain-text body.</td></tr><tr><td><code>html</code></td><td><code>string</code></td><td>no</td><td>HTML alternative. Sanitised; removals are reported.</td></tr><tr><td><code>attachments</code></td><td><code>string[]</code></td><td>no</td><td>File names inside <code>SMTP_ATTACHMENT_DIR</code>.</td></tr><tr><td><code>confirm_token</code></td><td><code>string</code></td><td>no</td><td>From a previous call with the same arguments. Omit on the first.</td></tr></tbody></table><p>There is no <code>from</code> parameter. The sender is <code>SMTP_FROM</code>.</p><h3 id="reply-mail" tabindex="-1"><code>reply_mail</code> <a class="header-anchor" href="#reply-mail" aria-label="Permalink to “reply_mail”">​</a></h3><p>Everything <code>send_mail</code> takes, plus:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>original_subject</code></td><td><code>string</code></td><td>yes</td><td>Subject of the message being answered. <code>Re: </code> is added if not present.</td></tr><tr><td><code>subject</code></td><td><code>string</code></td><td>no</td><td>Overrides the derived subject.</td></tr><tr><td><code>in_reply_to</code></td><td><code>string</code></td><td>yes</td><td>Message-ID of the original, verbatim.</td></tr><tr><td><code>references</code></td><td><code>string[]</code></td><td>no</td><td>The original&#39;s References chain, oldest first.</td></tr><tr><td><code>quote</code></td><td><code>string</code></td><td>no</td><td>Original text to quote below the reply.</td></tr></tbody></table><p>Pass <code>in_reply_to</code> and <code>references</code> through unchanged so mail clients thread the reply correctly. imap-mcp&#39;s <code>get_message</code> returns both.</p><h3 id="forward-mail" tabindex="-1"><code>forward_mail</code> <a class="header-anchor" href="#forward-mail" aria-label="Permalink to “forward_mail”">​</a></h3><p>Everything <code>send_mail</code> takes, plus:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>original_subject</code></td><td><code>string</code></td><td>yes</td><td>Subject of the message being forwarded. <code>Fwd: </code> is added if not present.</td></tr><tr><td><code>subject</code></td><td><code>string</code></td><td>no</td><td>Overrides the derived subject.</td></tr><tr><td><code>quote</code></td><td><code>string</code></td><td>no</td><td>The original text, included verbatim below your own.</td></tr><tr><td><code>references</code></td><td><code>string[]</code></td><td>no</td><td>The original&#39;s References chain.</td></tr></tbody></table><p>The quoted original is passed on unchanged. If it matches known prompt-injection shapes, the confirmation dialog says so rather than altering it.</p><p>Attachments of the original are not carried over automatically — save them into <code>SMTP_ATTACHMENT_DIR</code> and name them in <code>attachments</code>.</p><h2 id="the-essential-preset" tabindex="-1">The <code>essential</code> preset <a class="header-anchor" href="#the-essential-preset" aria-label="Permalink to “The essential preset”">​</a></h2><p><code>SMTP_ALLOW_TOOLS=essential</code> registers five: <code>get_server_info</code>, <code>validate_recipients</code>, <code>preview_mail</code>, <code>send_mail</code> and <code>reply_mail</code>.</p><p><code>forward_mail</code> is left out because forwarding carries somebody else&#39;s content and attachments outward, and <code>test_connection</code> is diagnostics rather than work.</p>`,36)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};